pub fn depthTestingAttrSlot(attr_name: []const u8) ?usize {
    if (std.mem.eql(u8, attr_name, "position")) {
        return 0;
    }
    if (std.mem.eql(u8, attr_name, "texcoord0")) {
        return 1;
    }
    return null;
}
pub fn depthTestingTextureSlot(tex_name: []const u8) ?usize {
    if (std.mem.eql(u8, tex_name, "tex")) {
        return 0;
    }
    return null;
}
pub fn depthTestingSamplerSlot(smp_name: []const u8) ?usize {
    if (std.mem.eql(u8, smp_name, "smp")) {
        return 0;
